#' Joinpoint Trend Analysis
#'
#' Fits a joinpoint (segmented log-linear) regression to a series of rates 
#' measured over time - the standard analysis for cancer-registry incidence 
#' and mortality trends. The number of joinpoints (change points in trend) is 
#' selected data-adaptively, and each segment is summarized by its Annual 
#' Percent Change (APC). The overall Average Annual Percent Change (AAPC) 
#' summarizes the whole period. Use it to detect when a rate began rising or 
#' falling and to quantify the rate of change in each period.
#' 
#'
#' @examples
#' \donttest{
#' joinpoint(
#'     data = mydata,
#'     time = "year",
#'     rate = "incidence_rate",
#'     maxJoinpoints = 3)
#'}
#' @param data The data as a data frame (one row per time point).
#' @param time Time variable (e.g. calendar year).
#' @param rate The rate or count measured at each time point. Modelled on the
#'   log scale, so all values must be positive.
#' @param maxJoinpoints The maximum number of joinpoints (change points) to
#'   consider. The best number up to this maximum is selected using the Bayesian
#'   Information Criterion.
#' @param conf_level Confidence level for APC / AAPC intervals.
#' @param showSegments Report the Annual Percent Change for each fitted
#'   segment.
#' @param showAAPC Report the Average Annual Percent Change over the whole
#'   period.
#' @param showPlot Display the observed rates with the fitted joinpoint trend.
#' @param logScale Plot the y-axis on a logarithmic scale (log-linear segments
#'   become straight).
#' @param showSummary Display a plain-language summary of the trend.
#' @param showExplanation Display an explanation of joinpoint regression.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$joinpointTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$segmentTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$aapcTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$joinpointTable$asDF}
#'
#' \code{as.data.frame(results$joinpointTable)}
#'
#' @export
joinpoint <- function(
    data,
    time,
    rate,
    maxJoinpoints = 3,
    conf_level = 0.95,
    showSegments = TRUE,
    showAAPC = TRUE,
    showPlot = TRUE,
    logScale = FALSE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("joinpoint requires jmvcore to be installed (restart may be required)")

    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(rate)) rate <- jmvcore::resolveQuo(jmvcore::enquo(rate))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(rate), rate, NULL))


    options <- joinpointOptions$new(
        time = time,
        rate = rate,
        maxJoinpoints = maxJoinpoints,
        conf_level = conf_level,
        showSegments = showSegments,
        showAAPC = showAAPC,
        showPlot = showPlot,
        logScale = logScale,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- joinpointClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

